"""Experiment recipes for Figures 2, 3, 4 and 6.

All experiments use the same candidate models with different observation,
communication and network settings. Saved arrays contain the plotted readouts.
"""

from dataclasses import replace
from pathlib import Path
from time import perf_counter

import numpy as np

from .model import Config, candidate_priors, gaussian_reference, rollout, jax, jnp


# Scientific settings are explicit: no parameter search or external data files.
SEEDS_CYCLE_NETWORK = np.arange(50)
SEEDS_CAMP = np.arange(10000, 10050)
SHIFT = 80  # Zero-based round: first shifted signal is observation index 80.
STEPS = {2: 240, 3: 5000, 4: 600, 6: 600}
AGENTS = {2: 16, 3: 16, 4: 24, 6: 24}
CAMP_BETA = 0.05
NETWORK_PHASE2_SEED_OFFSET = 1000
TOPOLOGIES = ("cycle", "wheel", "community", "complete")


def social_matrix(n, beta=0.5):
    """Two equal camps: each row assigns beta total weight to the other camp.

    Self contact is included. beta=0.5 is uniform all-to-all communication.
    """
    if n < 2 or n % 2 or not 0 <= beta <= 1:
        raise ValueError("Require two equal camps and beta in [0, 1]")
    block = np.ones((n // 2, n // 2)) / (n // 2)
    return np.block([[(1 - beta) * block, beta * block],
                     [beta * block, (1 - beta) * block]])


def network_adjacency(name):
    """Construct one of Figure 6's fixed, undirected 24-agent graphs.

    The wheel's hub is agent 0. The community graph has complete groups 0..3
    and 4..23 joined by seven fixed bridges. Self contact is added separately
    when converting adjacency to communication weights.
    """
    n = AGENTS[6]
    adjacency = np.zeros((n, n))
    if name == "cycle":
        nodes = np.arange(n)
        adjacency[nodes, (nodes + 1) % n] = 1
    elif name == "wheel":
        rim = np.arange(1, n)
        adjacency[0, rim] = 1
        adjacency[rim, np.roll(rim, -1)] = 1
    elif name == "community":
        adjacency[:4, :4] = 1
        adjacency[4:, 4:] = 1
        bridges = np.array([(0, 7), (1, 7), (1, 19), (2, 8),
                            (2, 10), (2, 22), (3, 23)])
        adjacency[bridges[:, 0], bridges[:, 1]] = 1
    elif name == "complete":
        adjacency[:] = 1
    else:
        raise ValueError(f"Unknown topology {name!r}; choose from {TOPOLOGIES}")
    adjacency = np.maximum(adjacency, adjacency.T)
    np.fill_diagonal(adjacency, 0)
    return adjacency


def signal_path(steps, shift=None):
    """Constant (C,G,M)=(1,1,1), optionally preceded by negative mass change."""
    signals = np.broadcast_to([0., 1., 1., 1.], (steps, 4)).copy()
    if shift is not None:
        signals[:shift, 3] = -1.0
    return signals


def _groups(history, split):
    """Average agents within each seed before comparing or bootstrapping seeds."""
    n = history["oxygen"].shape[2]
    groups = (np.arange(split), np.arange(split, n))
    return {"q_" + name: history["oxygen"][:, :, ids].mean(2)
            for name, ids in zip("AB", groups)}


def cycle(cfg, seeds, steps):
    """Figure 2: 16 full observers, one continuous random stream over the shift."""
    n = AGENTS[2]
    _, history = rollout(cfg, social_matrix(n), np.ones((n, 3)),
                         signal_path(steps, SHIFT), seeds)
    # Keep individual q so the plotted entropy is mean individual entropy,
    # which is different from entropy of the population-mean probability.
    return {"oxygen": history["oxygen"]}


def camps(cfg, seeds, steps):
    """Figure 3: one Gaussian and two candidate-weight conditions, paired seeds."""
    n = AGENTS[3]
    W, signals = social_matrix(n, CAMP_BETA), signal_path(steps)
    attention = np.zeros((n, 3))
    attention[:n // 2, 1] = 1.0  # First camp observes gas uptake only.
    attention[n // 2:, 2] = 1.0  # Second camp observes mass change only.
    cfg = replace(cfg, sigma=0.5, omega=0.3)
    gaussian_P, gaussian_h = gaussian_reference(cfg.P0, cfg.h0)
    conditions = {
        "G_plain_info": replace(cfg, P0=gaussian_P, h0=gaussian_h, alpha=0.0),
        "C10": replace(cfg, alpha=0.0),  # Share conditional beliefs only.
        "C11": replace(cfg, alpha=0.02),  # Also share model support.
    }
    values = {}
    for name, condition in conditions.items():
        print(f"  {name}: {len(seeds)} seeds × {steps} updates", flush=True)
        _, history = rollout(condition, W, attention, signals, seeds)
        mixture = history["mixture"]
        difference = (mixture[:, :, np.arange(n // 2)].mean(2)
                      - mixture[:, :, np.arange(n // 2, n)].mean(2))
        values[name + "__mixture_distance"] = np.linalg.norm(difference, axis=-1)
        if name != "G_plain_info":
            values.update({name + "__" + key: value
                           for key, value in _groups(history, n // 2).items()})
    return values


def network(cfg, seeds, steps):
    """Figure 4: four interventions branched from one common 80-round history.

    Nxy enables conditional-belief sharing when x=1 and model-weight sharing
    when y=1. After the world changes, agents 0..3 still observe everything;
    agents 4..23 assign only .01 attention to gas and mass evidence.
    """
    n = AGENTS[4]
    W, signals = social_matrix(n), signal_path(steps, SHIFT)
    full_attention = np.ones((n, 3))
    common_state, before = rollout(cfg, W, full_attention, signals[:SHIFT], seeds)
    # Clone beliefs and reset the second-phase RNG identically for all four
    # arms. Figure 2 instead continues its random stream through the shift.
    phase2_keys = jnp.stack([jax.random.PRNGKey(int(seed) + NETWORK_PHASE2_SEED_OFFSET)
                            for seed in seeds])
    branch_state = (*common_state[:3], phase2_keys)
    attention = full_attention.copy()
    attention[4:, 1:] = 0.01
    before_q, values = _groups(before, 4), {}
    for name in ("N00", "N10", "N01", "N11"):
        condition = replace(cfg, fuse=name[1] == "1",
                            alpha=0.02 if name[2] == "1" else 0.0)
        print(f"  {name}: {len(seeds)} seeds × {steps} updates", flush=True)
        _, after = rollout(condition, W, attention, signals[SHIFT:], seeds,
                           initial=branch_state)
        for key, value in _groups(after, 4).items():
            values[name + "__" + key] = np.concatenate((before_q[key], value), axis=1)
        # Full-signal MSE is against noiseless C,G,M, regardless of attention.
        mixture = np.concatenate((before["mixture"], after["mixture"]), axis=1)
        mse = np.mean((mixture - signals[None, :, None, 1:]) ** 2, axis=-1)
        for group, ids in (("A", np.arange(4)), ("B", np.arange(4, n))):
            # Full run: completed states 451..600, i.e. indices 450:600.
            values[name + "__mse_" + group + "_tail"] = (
                mse[:, :, ids].mean(2)[:, steps - steps // 4:].mean(1)
            )
    return values


def topology(cfg, seeds, steps):
    """Figure 6: compare the same attention intervention on four networks.

    Each graph has its own 80-update full-attention prehistory. The observation
    streams are paired across graphs, including the reset to seed+1000 at the
    shift. Agents 0..3 keep full attention; the remaining agents give gas and
    mass evidence weight .01. Both forms of communication stay enabled.
    """
    n = AGENTS[6]
    if steps <= SHIFT:
        raise ValueError(f"Topology experiments require more than {SHIFT} updates")
    signals = signal_path(steps, SHIFT)
    full_attention = np.ones((n, 3))
    attention = full_attention.copy()
    attention[4:, 1:] = .01
    phase2_keys = jnp.stack([jax.random.PRNGKey(int(seed) + NETWORK_PHASE2_SEED_OFFSET)
                            for seed in seeds])
    values = {"full_observers": np.arange(4)}
    for name in TOPOLOGIES:
        print(f"  {name}: {len(seeds)} seeds × {steps} updates", flush=True)
        adjacency = network_adjacency(name)
        self_contact = adjacency + np.eye(n)
        W = self_contact / self_contact.sum(axis=1, keepdims=True)
        state, before = rollout(cfg, W, full_attention, signals[:SHIFT], seeds)
        branch_state = (*state[:3], phase2_keys)
        _, after = rollout(cfg, W, attention, signals[SHIFT:], seeds,
                           initial=branch_state)
        oxygen = np.concatenate((before["oxygen"], after["oxygen"]), axis=1)
        values[name + "__adjacency"] = adjacency
        values[name + "__q_B"] = oxygen[:, :, 4:].mean(2)
        # Faint lines show individual restricted agents in the first seed;
        # the thick line and interval summarize all seed-level group means.
        values[name + "__individual_B"] = oxygen[0, :, 4:]
    return values


def run(figure: int, output_dir: Path, smoke: bool = False):
    """Save figureN.npz and return JSON-compatible execution metadata.

    Smoke mode uses three seeds; Figure 3 stops at 100 updates and Figures 4/6
    at 120. It checks execution and drawing, not the paper's numerical claims.
    Refuses to overwrite an existing archive; use a fresh output directory.
    """
    if figure not in (2, 3, 4, 6):
        raise ValueError("Choose Figure 2, 3, 4 or 6")
    output_dir = Path(output_dir)
    destination = output_dir / f"figure{figure}.npz"
    if destination.exists():
        raise FileExistsError(f"Existing result: {destination}; choose a fresh output directory")
    output_dir.mkdir(parents=True, exist_ok=True)
    start = perf_counter()
    seeds = SEEDS_CAMP if figure == 3 else SEEDS_CYCLE_NETWORK
    steps = STEPS[figure]
    if smoke:
        seeds = seeds[:3]
        steps = {2: 240, 3: 100, 4: 120, 6: 120}[figure]
    print(f"Figure {figure}: {'SMOKE' if smoke else 'paper'} experiment", flush=True)
    cfg = Config(*candidate_priors())
    # Figures 2 and 6 label the first post-update readout 0; Figures 3/4 use 1.
    arrays = {"seeds": seeds, "states": np.arange(steps) + (figure in (3, 4))}
    arrays.update({2: cycle, 3: camps, 4: network, 6: topology}[figure](cfg, seeds, steps))
    if any(not np.isfinite(value).all() for value in arrays.values()):
        raise FloatingPointError("Cannot save non-finite figure data")
    # Exclusive creation also prevents accidental overwrite if another process
    # wrote this filename while the simulation was running.
    with destination.open("xb") as stream:
        np.savez_compressed(stream, **arrays)
    settings = {
        "sigma_o": 0.5 if figure == 3 else cfg.sigma,
        "omega": 0.3 if figure == 3 else cfg.omega,
        "beta": CAMP_BETA if figure == 3 else 0.5,
        "signal_after": [0.0, 1.0, 1.0, 1.0],
        "jax_enable_x64": True,
        "random_generator": "threefry2x32",
        "conditions": {},
    }
    if figure == 2:
        settings.update(shift=SHIFT, signal_before=[0.0, 1.0, 1.0, -1.0],
                        attention=[1.0, 1.0, 1.0], phase2_rng="continuous")
        settings["conditions"]["cycle"] = {"K": 2, "fuse": True, "alpha_m": cfg.alpha}
    elif figure == 3:
        settings["attention"] = {"gas_agents_0_to_7": [0.0, 1.0, 0.0],
                                 "mass_agents_8_to_15": [0.0, 0.0, 1.0]}
        for name, k, alpha in (("G_plain_info", 1, 0.0), ("C10", 2, 0.0),
                               ("C11", 2, 0.02)):
            settings["conditions"][name] = {"K": k, "fuse": True, "alpha_m": alpha}
    elif figure == 4:
        settings.update(shift=SHIFT, signal_before=[0.0, 1.0, 1.0, -1.0],
                        phase2_rng_seed_offset=NETWORK_PHASE2_SEED_OFFSET,
                        common_prehistory={"updates": SHIFT, "attention": [1., 1., 1.],
                                           "fuse": True, "alpha_m": cfg.alpha},
                        attention={"full_agents_0_to_3": [1., 1., 1.],
                                   "restricted_agents_4_to_23": [1., .01, .01]},
                        mse_tail_completed_states=[steps - steps // 4 + 1, steps])
        for name in ("N00", "N10", "N01", "N11"):
            settings["conditions"][name] = {
                "K": 2, "fuse": name[1] == "1", "alpha_m": .02 if name[2] == "1" else 0.0}
    else:
        settings.pop("beta")  # Graph weights replace the two-camp parameter.
        settings.update(shift=SHIFT, signal_before=[0., 1., 1., -1.],
                        phase2_rng_seed_offset=NETWORK_PHASE2_SEED_OFFSET,
                        full_observers=list(range(4)),
                        prehistory={"updates": SHIFT, "attention": [1., 1., 1.],
                                    "separate_for_each_graph": True},
                        attention={"full_agents_0_to_3": [1., 1., 1.],
                                   "restricted_agents_4_to_23": [1., .01, .01]},
                        network_weights="W = (A + I) / row_sum(A + I)",
                        individual_trajectory_seed=int(seeds[0]))
        for name in TOPOLOGIES:
            settings["conditions"][name] = {"K": 2, "fuse": True, "alpha_m": cfg.alpha}
    return {"figure": figure, "mode": "smoke" if smoke else "paper",
            "agents": AGENTS[figure], "steps": steps, "seeds": seeds.tolist(),
            "settings": settings, "file": destination.name,
            "elapsed_seconds": perf_counter() - start}
